        ["ActivityReset"] = ["直近リセット成功：{0} / 成功回数 {1} / {2}秒前 / エリア {3} / 状態 {4}", "Last reset succeeded: {0} / count {1} / {2}s ago / territory {3} / state {4}", "Letztes Zurücksetzen erfolgreich: {0} / Anzahl {1} / vor {2}s / Gebiet {3} / Status {4}", "Dernière remise à zéro réussie : {0} / total {1} / il y a {2}s / zone {3} / état {4}", "최근 초기화 성공: {0} / 횟수 {1} / {2}초 전 / 지역 {3} / 상태 {4}", "最近重置成功：{0} / 次数 {1} / {2}秒前 / 区域 {3} / 状态 {4}", "最近重置成功：{0} / 次數 {1} / {2}秒前 / 區域 {3} / 狀態 {4}"],
        ["ShowDebug"] = ["デバッグ表示", "Show debug information", "Debug-Informationen anzeigen", "Afficher le débogage", "디버그 정보 표시", "显示调试信息", "顯示偵錯資訊"],
