        ["Stop"] = ["停止", "Stop", "Stoppen", "Arrêter", "중지", "停止", "停止"],
        ["BetweenWordsMs"] = ["送信後の待ち時間 (ms)", "Delay after submission (ms)", "Wartezeit nach Senden (ms)", "Délai après envoi (ms)", "전송 후 대기 시간 (ms)", "提交后的等待时间 (ms)", "提交後的等待時間 (ms)"],
